SELECT 
FROM mes_quality_inspection WHERE is_deleted = 0

    AND (report_no LIKE CONCAT('%', #{keyword}, '%')
         OR product_model LIKE CONCAT('%', #{keyword}, '%')
         OR batch_no LIKE CONCAT('%', #{keyword}, '%'))


    AND inspection_type = #{inspectionType}


    AND result = #{result}

ORDER BY id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM mes_quality_inspection WHERE is_deleted = 0

    AND (report_no LIKE CONCAT('%', #{keyword}, '%')
         OR product_model LIKE CONCAT('%', #{keyword}, '%')
         OR batch_no LIKE CONCAT('%', #{keyword}, '%'))


    AND inspection_type = #{inspectionType}


    AND result = #{result}
